    private static void put(String pt,String en,String es){STRINGS.put(pt,new String[]{en,es});}
    static String locale(Context context){String selected=context.getSharedPreferences("settings",0).getString("language","system");return resolve(selected,android.content.res.Resources.getSystem().getConfiguration().getLocales().get(0));}
    static String resolve(String selected,Locale system){if(!selected.equals("system"))return selected;switch(system.getLanguage()){case "pt":return "pt-BR";case "es":return "es-ES";default:return "en-US";}}
    static String tr(Context context,String value){String locale=locale(context);if(locale.startsWith("pt"))return value;String[] match=STRINGS.get(value);if(match!=null)return match[locale.startsWith("es")?1:0];if(value.startsWith("Voz:")){boolean es=locale.startsWith("es");return value.replace("Voz:",es?"Voz:":"Voice:").replace("o servidor não anunciou suporte a chatStream",es?"el servidor no anunció soporte para chatStream":"server did not announce chatStream support").replace("negociada · verificando envio de áudio",es?"negociada · verificando envío de audio":"negotiated · checking audio transmission").replace("falha na negociação",es?"error de negociación":"negotiation failed").replace("pacotes",es?"paquetes":"packets").replace("bytes enviados",es?"bytes enviados":"bytes sent").replace("nível",es?"nivel":"level").replace("estatísticas indisponíveis",es?"estadísticas no disponibles":"statistics unavailable");}return value;}
